#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# Walks the repository owner through the human-only production verification steps across #194, #531, #534,
# #536, #539, #113, #629, #118 and #622 in one sitting. Checks each step's precondition live before asking
# the human to act, skips steps whose product handlers answer 501 not-built (naming the blocking ticket),
# and writes paste-ready, redacted evidence into infra/wizards/production-pilot.evidence.md (git-ignored).
# Non-secret slugs and IDs go to infra/wizards/.env; SKYCLAUSE_API_KEY and email addresses stay in memory only.

PROJECT="${PROJECT:-skyclause}"
GCP_REGION="${GCP_REGION:-asia-southeast1}"
AWS_ACCOUNT="${AWS_ACCOUNT:-776566309118}"
SES_REGION="${SES_REGION:-ap-southeast-2}"
SES_EVENTS_TOPIC_ARN="${SES_EVENTS_TOPIC_ARN:-arn:aws:sns:ap-southeast-2:776566309118:skyclause-production-ses-events}"
MARKETING_ORIGIN="${MARKETING_ORIGIN:-https://skyclause.m1ku.tech}"
APP_ORIGIN="${APP_ORIGIN:-https://app.skyclause.m1ku.tech}"
API_ORIGIN="${API_ORIGIN:-https://api.skyclause.m1ku.tech}"
DOCS_ORIGIN="${DOCS_ORIGIN:-https://docs.skyclause.m1ku.tech}"
EVIDENCE_FILE="${EVIDENCE_FILE:-infra/wizards/production-pilot.evidence.md}"
SLUG_PATTERN='^[a-z0-9]+(-[a-z0-9]+)*$'
API_KEY_PATTERN='^skc_[A-Za-z0-9_-]{8,}$'

API_STATUS=""
API_BODY=""

# ask_valid ask|ask_secret KEY "Prompt" REGEX "Hint" asks until the answer matches REGEX, and stops
# the wizard if input ends.
ask_valid() {
  local read_with="$1" key="$2" prompt="$3" pattern="$4" hint="$5"
  while true; do
    "$read_with" "$key" "$prompt" || { warn "No input, so stopping."; exit 1; }
    [[ "${!key}" =~ $pattern ]] && return 0
    warn "$hint"
  done
}

# key_prefix KEY prints only the first 8 characters of an API key followed by an ellipsis.
key_prefix() {
  printf '%s…' "${1:0:8}"
}

# redact_text strips full skc_ API keys and personal email addresses from stdin before writing evidence.
redact_text() {
  python3 -c '
import re, sys
text = sys.stdin.read()
text = re.sub(r"\bskc_[A-Za-z0-9_-]{8,}\b", lambda m: m.group(0)[:8] + "…", text)
def redact_email(m):
    addr = m.group(0)
    if (
        addr.endswith("@skyclause.iam.gserviceaccount.com")
        or addr.endswith("@skyclause.m1ku.tech")
        or addr.endswith(".skyclause.m1ku.tech")
    ):
        return addr
    return "<redacted-email>"
text = re.sub(r"[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}", redact_email, text)
sys.stdout.write(text)
'
}

init_evidence() {
  [[ -e "$EVIDENCE_FILE" ]] || (umask 077 && printf '# Production pilot verification evidence\n' > "$EVIDENCE_FILE")
}

# record_evidence ISSUE TITLE COMMAND OUTPUT appends one redacted markdown section to EVIDENCE_FILE.
record_evidence() {
  local issue="$1" title="$2" cmd="$3" out="$4" fence='```' safe_cmd safe_out
  init_evidence
  safe_cmd="$(printf '%s' "$cmd" | redact_text)"
  safe_out="$(printf '%s' "$out" | redact_text)"
  {
    printf '\n## %s — %s (%s)\n\n' "$issue" "$title" "$(date -u +%Y-%m-%dT%H:%M:%SZ)"
    printf '%sshell\n$ %s\n%s\n\n' "$fence" "$safe_cmd" "$fence"
    printf '%stext\n%s\n%s\n' "$fence" "$safe_out" "$fence"
  } >> "$EVIDENCE_FILE"
  printf '  %s✓ recorded%s evidence for %s → %s\n' "$GREEN" "$RESET" "$issue" "$EVIDENCE_FILE"
}

# api_get PATH calls GET $API_ORIGIN$PATH with SKYCLAUSE_API_KEY passed over stdin, setting API_STATUS and API_BODY.
api_get() {
  local path="$1" raw
  raw="$(printf 'header = "Authorization: Bearer %s"\nheader = "Skyclause-Organization: %s"\nheader = "Accept: application/json"\n' \
    "$SKYCLAUSE_API_KEY" "$ORG_SLUG" | curl -sS -K - -w $'\n%{http_code}' "$API_ORIGIN$path")" || return 1
  API_STATUS="${raw##*$'\n'}"
  API_BODY="${raw%$'\n'*}"
}

# json_field EXPR readsAPI_BODY with python3 and prints the evaluated expression.
json_field() {
  local expr="$1"
  printf '%s' "$API_BODY" | python3 -c "import json, sys; data = json.load(sys.stdin); print($expr)" 2>/dev/null || true
}

run_wizard() {

TOTAL_STAGES=12
cd "$(dirname "${BASH_SOURCE[0]}")/../.."
# Not the root .env, which Bun loads in local development.
[[ "$ENV_FILE" == .env ]] && ENV_FILE=infra/wizards/.env

banner "Production pilot checks and human steps (#194, #531, #534, #536, #539, #113, #629, #118, #622)"

stage "Check tools, hosts and on-call contacts (#118, #629)"
for tool in curl python3 gcloud aws; do
  command -v "$tool" >/dev/null 2>&1 || { warn "$tool is missing: install it and re-run"; exit 1; }
done
for origin in "$MARKETING_ORIGIN" "$APP_ORIGIN" "$API_ORIGIN"; do
  if ! curl -fsS "$origin/health" >/dev/null; then
    warn "$origin/health did not answer 200; check production before continuing."
    exit 1
  fi
done
say "Production hosts ($MARKETING_ORIGIN, $APP_ORIGIN, $API_ORIGIN) answer /health with 200."
say "Checking ONCALL_CONTACTS in Secret Manager ($PROJECT) for #118 and #629..."
oncall_versions="$(gcloud secrets versions list ONCALL_CONTACTS --project="$PROJECT" --filter=state=ENABLED --format='value(name)' 2>/dev/null | wc -l | tr -d ' ')"
if (( oncall_versions == 0 )); then
  warn "ONCALL_CONTACTS has no enabled version yet (#118, #629)."
  note "Run ./infra/wizards/oncall-contacts.sh yourself (about 10 minutes): it stores the contacts, and a second"
  note "run after oncall_contacts_ready is applied verifies the SMS numbers. Then re-run this wizard."
fi
if (( oncall_versions > 0 )); then
  oncall_list="$(gcloud secrets versions list ONCALL_CONTACTS --project="$PROJECT" --filter=state=ENABLED --format='table(name,state,createTime)')"
  record_evidence "#118 / #629" "ONCALL_CONTACTS enabled versions (checked by name, never access)" \
    "gcloud secrets versions list ONCALL_CONTACTS --project=$PROJECT --filter=state=ENABLED --format='table(name,state,createTime)'" \
    "$oncall_list"
else
  SKIPPED+=("#118 / #629: run ./infra/wizards/oncall-contacts.sh to store ONCALL_CONTACTS and verify SMS channels")
fi
pause

stage "Check deploy criteria still blocked (#622)"
say "Checking #622's remaining deploy criteria live..."
if ! grep -q '"build"' apps/docs/package.json 2>/dev/null; then
  warn "#622 web image docs export: not built yet, waits on #210 (apps/docs has no build script)."
  SKIPPED+=("#622 web image contains the docs export (waits on #210)")
else
  docs_status="$(curl -sS -o /dev/null -w '%{http_code}' "$DOCS_ORIGIN/")"
  record_evidence "#622" "Docs host status" "curl -sS -o /dev/null -w '%{http_code}' $DOCS_ORIGIN/" "HTTP $docs_status"
fi
if gcloud run jobs describe commons-provision --region="$GCP_REGION" --project="$PROJECT" >/dev/null 2>&1; then
  commons_out="$(gcloud run jobs executions list --job=commons-provision --region="$GCP_REGION" --project="$PROJECT" --limit=1 --format='table(name,status.completionTime,status.succeededCount)')"
  record_evidence "#622" "commons:provision execution" \
    "gcloud run jobs executions list --job=commons-provision --region=$GCP_REGION --project=$PROJECT --limit=1" \
    "$commons_out"
else
  warn "#622 commons:provision after migrate: not built yet, waits on #179 (job commons-provision not in Cloud Run)."
  SKIPPED+=("#622 commons:provision runs after migrate (waits on #179)")
fi
note "#622 failing migrate rehearsal is tracked separately against a throwaway Neon branch; GitHub Actions deploy waits on billing recovery."
SKIPPED+=("#622 end-to-end deploy on GitHub Actions (waits on GitHub Actions billing)")
pause

stage "Sign in (#194)"
open_url "$APP_ORIGIN/sign-in"
step "Sign in to $APP_ORIGIN with Google, or with a link sent to your email address."
note "While SES is in the sandbox, a sign-in link reaches only an address verified with ./infra/wizards/staff-and-ses.sh."
pause "Press Enter once you are signed in to $APP_ORIGIN in the browser"

stage "Create the organisation and pilot project (#194)"
ask_valid ask ORG_SLUG "Production organisation slug:" "$SLUG_PATTERN" "Use lowercase letters, digits and hyphens."
write_env ORG_SLUG "$ORG_SLUG"
ask_valid ask PROJECT_SLUG "Production pilot project slug:" "$SLUG_PATTERN" "Use lowercase letters, digits and hyphens."
write_env PROJECT_SLUG "$PROJECT_SLUG"
say "If the organisation and project already exist in production, press Enter to verify them in the next stage."
if confirm "Open $APP_ORIGIN/new and $APP_ORIGIN/$ORG_SLUG/new to create them now?"; then
  open_url "$APP_ORIGIN/new"
  step "Create the organisation with slug '$ORG_SLUG' (if not already created)."
  open_url "$APP_ORIGIN/$ORG_SLUG/new"
  step "Create the project with slug '$PROJECT_SLUG', the Bukit Jalil site coordinates, time zone Asia/Kuala_Lumpur, and the Sky pack ticked."
  note "Creating the project with Sky ticked publishes the default Sky clause sheet (v1)."
  note "The redirect to /$ORG_SLUG/$PROJECT_SLUG/settings/packs will show an error banner until #138 is built; the project itself is saved."
  pause "Press Enter once the project is created"
fi

stage "Create a read API key and verify project & Sky sheet (#194)"
open_url "$APP_ORIGIN/$ORG_SLUG/settings/api-keys"
say "We need a read-scope API key for '$ORG_SLUG' to run live read checks and #194's @production suite."
step "If #105 (a-keys-ui) is live on that page, create a key with scope 'read' and copy it."
step "While the settings panel is still a placeholder (#105), #106's backend route is live; run this in the"
note "  browser DevTools console on $APP_ORIGIN/$ORG_SLUG/settings/api-keys (requires sign-in within the last 10 minutes):"
note "  fetch('/api/orgs/$ORG_SLUG/api-keys',{method:'POST',headers:{'content-type':'application/json','idempotency-key':crypto.randomUUID()},body:JSON.stringify({name:'production-pilot',scopes:['read'],expires_in_days:90})}).then(r=>r.json()).then(d=>console.log(d.key))"
ask_valid ask_secret SKYCLAUSE_API_KEY "Paste the read API key (hidden, never saved to disk):" "$API_KEY_PATTERN" \
  "An API key starts with skc_."
KEY_HINT="$(key_prefix "$SKYCLAUSE_API_KEY")"
say "Verifying project '$PROJECT_SLUG' in '$ORG_SLUG' with key $KEY_HINT..."
api_get "/v1/projects?slug=$PROJECT_SLUG&include=summary"
if [[ "$API_STATUS" != "200" ]]; then
  warn "GET /v1/projects?slug=$PROJECT_SLUG&include=summary answered HTTP $API_STATUS: $API_BODY"
  exit 1
fi
PROJECT_ID="$(json_field "data['data'][0]['id'] if data.get('data') else ''")"
if [[ -z "$PROJECT_ID" ]]; then
  warn "No project with slug '$PROJECT_SLUG' found in organisation '$ORG_SLUG'. Create it in stage 4 and re-run."
  exit 1
fi
write_env PROJECT_ID "$PROJECT_ID"
project_summary="$API_BODY"
api_get "/v1/projects/$PROJECT_ID/clause-sheets"
sheets_body="$API_BODY"
record_evidence "#194" "Organisation, project and default Sky clause sheet (API key $KEY_HINT)" \
  "curl -fsS -H 'Authorization: Bearer $KEY_HINT' -H 'Skyclause-Organization: $ORG_SLUG' '$API_ORIGIN/v1/projects?slug=$PROJECT_SLUG&include=summary' && curl -fsS -H 'Authorization: Bearer $KEY_HINT' -H 'Skyclause-Organization: $ORG_SLUG' '$API_ORIGIN/v1/projects/$PROJECT_ID/clause-sheets'" \
  "$(printf '%s\n%s' "$project_summary" "$sheets_body")"
pause

stage "Verify the ledger chain and pilot archive (#531)"
api_get "/v1/projects/$PROJECT_ID/ledger/verify"
if [[ "$API_STATUS" == "200" ]] && [[ "$(json_field "data.get('valid')")" == "True" ]]; then
  printf '  %s✓ verified%s /v1/projects/%s/ledger/verify answered valid=true\n' "$GREEN" "$RESET" "$PROJECT_ID"
  record_evidence "#531" "Production /ledger/verify for the pilot project" \
    "curl -fsS -H 'Authorization: Bearer $KEY_HINT' -H 'Skyclause-Organization: $ORG_SLUG' '$API_ORIGIN/v1/projects/$PROJECT_ID/ledger/verify'" \
    "$API_BODY"
else
  warn "GET /v1/projects/$PROJECT_ID/ledger/verify answered HTTP $API_STATUS: $API_BODY"
  SKIPPED+=("#531 verify ledger chain")
fi
api_get "/v1/projects/$PROJECT_ID/pilot-archive"
archive_count="$(json_field "len(data.get('data', []))")"
if [[ "$API_STATUS" == "200" ]] && (( ${archive_count:-0} > 0 )); then
  record_evidence "#531" "Pilot archive objects" \
    "curl -fsS -H 'Authorization: Bearer $KEY_HINT' -H 'Skyclause-Organization: $ORG_SLUG' '$API_ORIGIN/v1/projects/$PROJECT_ID/pilot-archive'" \
    "$API_BODY"
else
  note "Pilot archive (#531 criterion 2) has 0 objects: the pilot-archive job runs after 17 November 2026 (infra/README.md 'Pilot archive')."
  SKIPPED+=("#531 upload and run pilot-archive job (after 17 November 2026)")
fi
